        values[(head+size)%values.size]=value;
        size++;
        return true
    };
    fun deQueue():Boolean{
        if(isEmpty())return false;
        head=(head+1)%values.size;
        size--;
        return true
    };
    fun Front():Int=if(isEmpty())-1 else values[head];
